# ints, floats, operators
print(7 + 3, 7 - 3, 7 * 3, 7 % 3, -7 % 3, 7 % -3)
print(7 // 2, -7 // 2, 7 // -2, -7 // -2)
print(2 ** 10, 2 ** 0, (-2) ** 3, 2 ** -1)
print(1 + 2 * 3, (1 + 2) * 3, 2 ** 3 ** 2, -2 ** 2)
print(10 / 4, 9 / 3, 1 / 3)
print(0.1 + 0.2, 1.5 * 2, 3.0 - 1, 2.5 // 1, 2.5 % 1)
print(1e3, 1.5e-3, 123456789.0, 0.000001, 1e16, 1e-7)
print(int(3.9), int(-3.9), float(3), int("42"), float("2.5"), int("-7"))
print(abs(-5), abs(2.5), abs(-0.0))
print(min(3, 1, 2), max(3, 1, 2), min([4, 2, 8]), max([4, 2, 8]))
print(round(2.5), round(3.5), round(2.675, 2), round(-1.5), round(7))
print(divmod(17, 5), divmod(-17, 5))
print(1 << 10, 1024 >> 3, 6 & 3, 6 | 3, 6 ^ 3, ~5)
print(True + True, True * 3, False + 1, int(True), float(False))
print(1 == 1.0, 1 is 1, 0.1 + 0.2 == 0.3, 2 < 3 < 4, 3 < 2 < 4)
print(1 < 2 and 2 < 3, 1 < 2 or 1 / 0 if False else "skip")
print(10 > 9 > 8, 1 != 1.0, "a" < "b", "abc" < "abd", "Z" < "a")
big = 2 ** 40
print(big, big * big, big // 7, -big % 7)
print(9007199254740993, 2 ** 62, 2 ** 63 - 1)
x = 5
x += 2; x -= 1; x *= 3; x //= 2; x %= 5; x **= 2; x <<= 1; x >>= 1; x |= 8; x &= 12; x ^= 5
print(x)
print(3 * 1.5, 3 / 1.5, 7.0 // 2, 7.0 % 2, -7.0 // 2)
print(float("inf") > 1e308, -float("inf") < 0, float("nan") == float("nan"))
print(0.1 * 3, 1 / 7, 2 / 3, 100.0 / 3)
print(1e20, 1e21, 1e22, 123456789012345678.0)
print(1.0, 2.50, 3.14159, -0.5, 1e-5, 0.0001)
print(5 % 2.5, 5.5 % 2, 2 ** 0.5)
